import sys
from collections import deque

class TreeNode:
    def __init__(self, val=0):
        self.val = val
        self.left = None
        self.right = None

def build_tree_from_level_order(values):
    if not values:
        return None

    root = TreeNode(int(values[0]))
    queue = deque([root])
    i = 1

    while queue and i < len(values):
        node = queue.popleft()

        if i < len(values):
            if values[i] != 'N' and values[i] != -1:
                node.left = TreeNode(int(values[i]))
                queue.append(node.left)
            i += 1

        if i < len(values):
            if values[i] != 'N' and values[i] != -1:
                node.right = TreeNode(int(values[i]))
                queue.append(node.right)
            i += 1

    return root

def convert_to_sum_tree(node):
    if not node:
        return 0

    left_sum = convert_to_sum_tree(node.left)
    right_sum = convert_to_sum_tree(node.right)

    original_val = node.val
    node.val = left_sum + right_sum

    return original_val + left_sum + right_sum

def preorder_traversal(node, result):
    if not node:
        return
    result.append(str(node.val))
    preorder_traversal(node.left, result)
    preorder_traversal(node.right, result)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    if n == 0:
        print("")
        return

    values = data[1:n+1]
    root = build_tree_from_level_order(values)
    convert_to_sum_tree(root)

    result = []
    preorder_traversal(root, result)
    print(" ".join(result))

if __name__ == "__main__":
    main()
